//! Cross-check against CORA: `tests/cora/generate.m` runs CORA's
//! `linearSys/oneStep` step by step on a few systems and writes the interval
//! hulls of its reachable sets to `tests/cora/reference.txt`. [`LinearReach`]
//! steps the same systems from the same sets and must match them.

use std::collections::HashMap;

use nalgebra::{DMatrix, DVector};
use polyzonotope::{IntervalBox, SparsePolyZonotope, Zonotope};
use polyzonotope_reach::{LinearReach, LinearSystem};

/// The reference file, regenerated by `tests/cora/generate.m`.
const REFERENCE: &str = include_str!("cora/reference.txt");

/// One case: its matrices by name, each stored column-major.
type Case = HashMap<String, DMatrix<f64>>;

/// Every case in the reference file.
fn cases() -> Vec<Case> {
    let mut cases = Vec::new();
    for line in REFERENCE.lines().filter(|l| !l.starts_with('#')) {
        let mut words = line.split_whitespace();
        let name = words.next().expect("every line starts with a name");
        if name == "case" {
            cases.push(Case::new());
            continue;
        }

        let mut number = || {
            words
                .next()
                .expect("a value")
                .parse::<f64>()
                .expect("a number")
        };
        let (rows, cols) = (as_count(number()), as_count(number()));
        let values: Vec<f64> = (0..rows * cols).map(|_| number()).collect();
        let case = cases.last_mut().expect("a case header comes first");
        case.insert(
            name.to_owned(),
            DMatrix::from_column_slice(rows, cols, &values),
        );
    }

    // An empty or truncated reference would make every check pass vacuously.
    assert_eq!(
        cases.len(),
        4,
        "tests/cora/reference.txt should hold four cases"
    );
    cases
}

/// A non-negative whole number read as `f64`, as a count.
#[expect(
    clippy::cast_possible_truncation,
    clippy::cast_sign_loss,
    reason = "sizes and counts in the reference file are small whole numbers"
)]
fn as_count(x: f64) -> usize {
    x as usize
}

/// The scalar stored under `name`.
fn scalar(case: &Case, name: &str) -> f64 {
    case[name][(0, 0)]
}

/// The center column of `name` as a vector.
fn column(case: &Case, name: &str) -> DVector<f64> {
    case[name].column(0).into_owned()
}

/// The time-point and time-interval hulls of every step, as `LinearReach`
/// computes them for `case`.
fn ours(case: &Case) -> Vec<(IntervalBox, IntervalBox)> {
    let system = LinearSystem {
        a: case["A"].clone(),
        b: case["B"].clone(),
    };
    let reach = LinearReach::new(system, scalar(case, "r"), as_count(scalar(case, "terms")))
        .expect("the reference step is small enough");
    let u = Zonotope::new(column(case, "cu"), case["GU"].clone());
    let mut x =
        SparsePolyZonotope::from_zonotope(&Zonotope::new(column(case, "c"), case["G"].clone()));

    (0..as_count(scalar(case, "steps")))
        .map(|_| {
            let step = reach.step(&x, &u);
            let hulls = (
                step.time_point.interval_hull(),
                step.time_interval.interval_hull(),
            );
            x = step.time_point;
            hulls
        })
        .collect()
}

/// The hull of step `k` from a reference matrix: lower bounds, then upper
/// bounds, in column `k`.
fn theirs(hulls: &DMatrix<f64>, k: usize) -> Vec<(f64, f64)> {
    let n = hulls.nrows() / 2;
    (0..n).map(|i| (hulls[(i, k)], hulls[(n + i, k)])).collect()
}

/// The largest distance between matching bounds of `ours` and `theirs`,
/// relative to the width of the reference hull.
fn mismatch(ours: &IntervalBox, theirs: &[(f64, f64)]) -> f64 {
    ours.0
        .iter()
        .zip(theirs)
        .map(|(iv, &(lo, hi))| (iv.lo - lo).abs().max((iv.hi - hi).abs()) / (hi - lo))
        .fold(0.0, f64::max)
}

/// The time-point sets are `e^{Ar} X` plus the input responses on both
/// sides, so their hulls agree up to the different remainder bounds: within
/// 1e-5 of the width, where the ten steps here differ by at most 7.2e-6.
#[test]
fn time_point_hulls_match_cora() {
    for (k, case) in cases().iter().enumerate() {
        for (s, (point, _)) in ours(case).iter().enumerate() {
            let gap = mismatch(point, &theirs(&case["time_point"], s));
            assert!(gap < 1e-5, "case {}, step {}: {gap}", k + 1, s + 1);
        }
    }
}

/// Over the step, both sides enclose the hull of the step ends with the
/// curvature corrections `F X` and `F̃ u` of Althoff (2010), with the same
/// `F` up to the remainder bounds. Under Octave, CORA cannot multiply an
/// interval matrix with a zonotope and falls back to `F □X`, the product
/// with the interval hull, where [`LinearReach`] maps the zonotope by the
/// center of `F` and boxes only the radius. Neither encloses the other, so
/// the hulls agree within 1% of the width, where the ten steps here differ
/// by at most 0.54%. The gap must not grow
/// with the steps: when the hull lost the pairing of the input generators
/// of `X` with their images, it reached 18% after ten steps.
#[test]
fn time_interval_hulls_match_cora() {
    for (k, case) in cases().iter().enumerate() {
        for (s, (_, during)) in ours(case).iter().enumerate() {
            let gap = mismatch(during, &theirs(&case["time_interval"], s));
            assert!(gap < 1e-2, "case {}, step {}: {gap}", k + 1, s + 1);
        }
    }
}
